+                                        }
+                                    }
+                                }
+                                fprintf(dumpstream, "COLON_KERNEL_DUMP_END\n");
+                                fflush(dumpstream);
+                                if (dumpstream != VERBSTREAM) {
+                                    fclose(dumpstream);
+                                }
+                            }
                         }

